/* 人手培养与约定：人物成长写入既有世界档案，雇佣仅持有排程和预算。 */
(()=>{'use strict';
const S=XTSandbox,W=XTWorld36,C=XTContent47,V=S.view;
const old={dispatch:S.dispatch,scene:renderScene,restore};
const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const wage=w=>C.staffWage(w),currency=w=>w.currency||'stone',payText=w=>C.coinText(wage(w),currency(w)),worker=id=>G?.sandbox35?.staff?.find(w=>w.id===id);
let notice='';
function log(text){addLog(text,'mute');}
function history(w,text){if(w.contract){w.contract.history=[...(w.contract.history||[]),{day:S.now(),text}].slice(-16);}log(w.name+'：'+text);}
function atHome(){const d=G?.sandbox35,p=d?.property;return !!p&&p.place===G.place&&['home','alchemy','forge'].includes(d.room)&&(!p.expires||p.expires>S.now());}
function pending(w){return w.contract?.kind==='personal'&&w.contract.status==='pending';}
function actor(n,place,day=S.now()){const p=G.sandbox35?.property,valid=p?.place===place&&(!p.expires||p.expires>day);return {realm:n.realm,layer:n.layer||1,cult:n.cult||0,root:n.root,coef:ROOTS[n.root]?.coef||0,place,age:Number.isFinite(n.birth)?Math.max(0,(day-n.birth)/360):null,lifespan:n.life,injured:(n.staff54?.injuredUntil||0)>day?1:0,buff:{},arts:{},learned:{},equipment:{},log:[],sandbox35:{property:valid?{...p,expires:null}:null,room:'home',mind:null,books:{}},qi51:{ownerId:'staff54_'+n.id,aux:[]},world36:{playerId:'staff54_'+n.id}};}
function debtOf(id){return G?.world36?.people?.[id]?.staff54?.unpaidWages||0;}
function debtCurrency(id){return G?.world36?.people?.[id]?.staff54?.unpaidCurrency||'stone';}
function recordDebt(w){if(!w.arrears||w.debtRecorded)return;const n=G.world36?.people?.[w.id];if(!n)return;n.staff54=n.staff54||{};const e=n.staff54;if(e.unpaidWages&&debtCurrency(w.id)!==currency(w))throw Error('欠薪币种冲突');e.unpaidCurrency=currency(w);e.unpaidWages=(e.unpaidWages||0)+w.arrears*wage(w);w.debtRecorded=true;history(w,'离职时保留未付月俸'+C.coinText(w.arrears*wage(w),currency(w))+'，由产业后人接续处理。');}
function reason(w){if(!w)return '这位人手已不在当前产业。';const n=W.get(w.id);if(!W.alive(n))return '对方已故，无法安排。';if(!atHome())return '须亲自到产业院落商议。';if(pending(w))return '个人聘约待后人当面确认。';if(w.arrears)return '须先结清欠薪。';return '';}
function trainReason(w){const why=reason(w);if(why)return why;const n=W.get(w.id),p=G.sandbox35.property;if(n.realm<0)return '凡人没有已核定的修行资质，不能直接安排修士培养。';if(!ROOTS[n.root])return '本人灵根尚未核定，暂不能计算修炼。';if(w.job||w.training)return '当前已有工作或培养安排。';if(!qiGateStatus(actor(n,p.place)).enough)return '产业所在地灵气不足以支撑本人当前境界。';if(realmBrim(actor(n,p.place)))return '本人已圆满，请先商议突破。';if(p.expires&&p.expires<S.now()+30)return '租期不足三十日，须先续租。';if(G.stones<wage(w))return '灵石不足以支付本期培养预算。';return '';}
function stop(w,why){const t=w.training;if(!t)return;const refund=t.budget-t.spent;if(refund>0)stoneChange(G,refund,'人手培养未用预算退回');const person=G.world36?.people?.[w.id];if(person){person.staff54=person.staff54||{};person.staff54.budgetRemainder=((t.carry||0)+t.budget*(t.last-t.start))%30;}w.training=null;log(w.name+'结束本期培养（'+why+'），已用'+t.spent+'灵石'+(refund?'，退回'+refund+'灵石':'')+'。');}
function tick(){const d=G?.sandbox35;if(!d)return;const now=S.now();for(const w of d.staff){const t=w.training;if(!t)continue;const n=G.world36?.people?.[w.id];if(!n){stop(w,'人物档案缺失');continue;}const p=d.property;let end=Math.min(now,t.end,Number.isFinite(n.birth)&&Number.isFinite(n.life)?n.birth+n.life*360:t.end,p?.expires??t.end);
 if(n.alive===false||!p||p.place!==t.place||w.arrears||pending(w))end=t.last;
 for(let day=t.last;day<end;day++){const a=actor(n,t.place,day);if(!qiGateStatus(a).enough)break;const prev=n.layer;gainCult(a,yearOutput(a)/360);n.cult=a.cult;n.layer=a.layer;w.realm=n.realm;if(n.layer!==prev)log(w.name+'修为精进，晋至'+realmLayerName(n.realm,n.layer)+'。');t.last=day+1;t.spent=Math.floor(((t.carry||0)+t.budget*(t.last-t.start))/30);if(realmBrim(a))break;}
 if(t.last>=t.end)stop(w,'三十日已满');else if(realmBrim(actor(n,t.place)))stop(w,'本人已至圆满');else if(t.last<end||now>=end&&end<Math.min(now,t.end)||n.alive===false||!p||p.place!==t.place||w.arrears||pending(w))stop(w,'当前条件中止');
 }}
function inherit(from,to){tick();for(const w of G.sandbox35?.staff||[]){const c=w.contract;if(c?.kind==='personal'&&c.holder===from){stop(w,'旧主去世，待当面协商');c.status='pending';c.successor=to;history(w,'旧主去世，预付工作与欠薪保留，等待后人商议聘约。');}}}
function transact(fn){const ok=C.atomic(fn);if(!ok)notice=C.takeFailure()||'保存失败，本次安排已撤回。';render();return ok;}
function settleDebt(w){const fee=(w.arrears||0)*wage(w);if(!fee){notice='眼下没有欠薪。';return false;}if(C.funds(currency(w))<fee){notice='钱款不足以结清'+C.coinText(fee,currency(w))+'欠薪。';return false;}C.debit(currency(w),fee,'补付人手欠薪');w.arrears=0;history(w,'结清欠薪'+C.coinText(fee,currency(w))+'。');return true;}
function breakQuote(w,investment=0){const n=w&&W.get(w.id),p=G?.sandbox35?.property;if(!n)return {reason:'人物档案缺失。'};if(!Number.isFinite(n.birth)||!Number.isFinite(n.life)||!ROOTS[n.root])return {reason:'本人年龄、寿限或灵根尚未核定，无法核算突破。'};const a=actor(n,p?.place||n.place),next=n.realm+1;if(next>=REALMS.length)return {reason:'本批不处理人手飞升。'};const why=reason(w);if(why)return {reason:why};if(w.job||w.training)return {reason:'先结束当前工作或培养。'};if(!realmBrim(a))return {reason:'本人尚未修至当前境界圆满。'};if(!qiGateStatus(a).enough)return {reason:'当前环境不足以支撑本人当前境界。'};
 const spend=Math.max(0,Math.min(Math.floor(G.stones),Math.floor(Number(investment)||0)));let mod=(a.coef-.95)*2+Math.min(.20,spend/200*.05);if(a.injured)mod-=.05;if(a.age>a.lifespan*.8)mod-=.05;return {reason:'',investment:spend,rate:Math.max(.05,Math.min(.95,REALMS[next].bt[0]*(1+mod))),next};}
function dispatch(type,arg=''){const [id,value]=String(arg).split(':'),w=worker(id);notice='';if(!systemReady())return false;if(type==='payFormer'){const fee=debtOf(id);if(!fee||w)return false;if(!W.present(id)||S.state().room!=='agency'){notice='须到县城牙行与本人当面结清。';render();return false;}const coin=debtCurrency(id);if(C.funds(coin)<fee){notice='对应钱款不足以结清旧欠款。';render();return false;}return transact(()=>{C.debit(coin,fee,'结清离职人手旧欠薪');W.get(id).staff54.unpaidWages=0;log(W.get(id).name+'收到旧欠薪'+C.coinText(fee,coin)+'。');});}if(!w)return false;
 if(type==='train'){const why=trainReason(w);if(why){notice=why;render();return false;}return transact(()=>{const fee=wage(w),n=W.get(id);n.cult=n.cult||0;n.staff54=n.staff54||{};stoneChange(G,-fee,'人手三十日培养预算');w.training={start:S.now(),end:S.now()+30,last:S.now(),budget:fee,spent:0,carry:n.staff54.budgetRemainder||0,place:G.sandbox35.property.place};history(w,'安排三十日培养，预付'+fee+'灵石，月俸另计。');});}
 if(type==='cancel'){if(!w.training)return false;return transact(()=>{tick();stop(w,'主动取消');});}
 if(type==='debt'){if(!atHome()){notice='请到产业院落当面结薪。';render();return false;}return transact(()=>settleDebt(w));}
 if(type==='personal'||type==='estate'||type==='accept'){const why=reason(w);if(why&&!(type==='accept'&&pending(w)&&atHome()&&!w.arrears)){notice=why;render();return false;}if(w.job||w.training){notice='请先完成已有安排，再商议新约。';render();return false;}if(type==='accept'&&!pending(w))return false;return transact(()=>{if(type==='accept'){w.contract.holder=G.world36.playerId;w.contract.status='active';delete w.contract.successor;}else w.contract={kind:type==='personal'?'personal':'estate',holder:G.world36.playerId,status:'active',since:S.now(),history:w.contract?.history||[]};history(w,type==='accept'?'与后人当面确认继续履约。':type==='personal'?'当面议定个人聘约；旧主去世后由后人重新商议。':'议定产业雇佣，随产业延续。');});}
 if(type==='leave'){const why=reason(w);if(why&&!(pending(w)&&atHome()&&!w.arrears)){notice=why;render();return false;}if(w.job){notice='预付工作尚未完成，请先完成或明确取消工作。';render();return false;}return transact(()=>{tick();stop(w,'协商结束聘约');history(w,'双方协商结束聘约。');G.sandbox35.staff=G.sandbox35.staff.filter(x=>x.id!==id);});}
 if(type==='break'){const q=breakQuote(w,value);if(q.reason){notice=q.reason;render();return false;}return transact(()=>{const n=W.get(id);stoneChange(G,-q.investment,'人手突破投入');n.staff54=n.staff54||{};if(Math.random()<q.rate){n.realm=q.next;n.layer=1;n.cult=0;n.life=realmLife(n.realm);w.realm=n.realm;w.life=n.life;history(w,'突破'+REALM_NAMES[n.realm]+'成功，寿限随境界更新。');}else{n.cult=Math.floor(realmNeed(n.realm,realmLayerCount(n.realm))*.75);n.life=Math.max((S.now()-n.birth)/360+1,n.life-3);n.staff54.injuredUntil=S.now()+3*360;w.life=n.life;history(w,'突破失败，修为减少25%、寿限减少三年，带伤三年。');}});}
 return false;}
function btn(label,type,id,disabled=false){return '<button class="sb-btn" data-staff54="'+type+'" data-person="'+esc(id)+'" '+(disabled?'disabled':'')+'>'+esc(label)+'</button>';}
function panel(w){const n=W.get(w.id),t=w.training,q=breakQuote(w),why=trainReason(w),c=w.contract;const title=n?(n.realm<0?'凡人':n.realm===0?'炼气'+(n.layer>=13?'圆满':CN_NUM[n.layer||1]+'层'):objRealmTxt(n)):'人物待核';return '<section class="staff54-workspace"><header><span>人手 · 成长与约定</span><h3>'+esc(w.name)+' · '+esc(title)+'</h3><p>'+esc(n?.root||'资质未录')+' · '+(W.age(n)==null?'年龄未核定':W.age(n)+'岁')+' / 寿限'+(n?.life??'未录')+'岁 · 月俸 '+payText(w)+' · '+(t?'正在培养':w.job?'正在委派':'暂无安排')+'</p></header>'+(notice?'<p class="staff54-notice" role="status">'+esc(notice)+'</p>':'')+'<div class="staff54-grid"><section><h4>修行培养</h4><p>修为 '+Number((n?.cult||0).toFixed(3))+' / '+(n&&n.realm>=0?realmNeed(n.realm,n.layer||1):'—')+'</p>'+(t?'<p>已修炼 '+(t.last-t.start)+' / 30日 · 已用预算 '+t.spent+' / '+t.budget+'灵石</p>'+btn('结束培养，结清余款','cancel',w.id):(n?.realm<0?'<p>凡人按聘约办理日常工作，暂无修士培养安排。</p>':'<p>三十日培养预算 '+wage(w)+'灵石，月俸另计。安排后随世界日期积累。</p>')+(why?'<p class="staff54-muted">'+esc(why)+'</p>':'')+btn('安排三十日培养','train',w.id,!!why))+(!q.reason?'<details class="staff54-break"><summary>商议突破'+esc(REALM_NAMES[q.next])+'</summary><p>投入无论成败均消耗。失败修为减少25%、寿限减少三年并带伤三年；未录悟性不额外加成。</p><label>本次投入灵石 <input data-staff54-invest type="number" min="0" max="'+Math.floor(G.stones)+'" step="1" value="0"></label><p data-staff54-rate>当前成算 '+Math.round(q.rate*100)+'%</p>'+btn('确认风险，尝试突破','break',w.id)+'</details>':'')+'</section><section><h4>聘约与账目</h4><p>'+(c?.kind==='personal'?'个人聘约 · '+(pending(w)?'待后人确认':'履行中'):'产业雇佣 · 随产业接续')+'</p><p>欠薪 '+(w.arrears||0)+'个月'+(w.arrears?'，合计 '+C.coinText((w.arrears||0)*wage(w),currency(w)):'')+'</p>'+(w.arrears?btn('结清已有欠薪','debt',w.id):'')+(pending(w)?btn('与旧部商议继续履约','accept',w.id):btn(c?.kind==='personal'?'改议产业雇佣':'商议个人聘约',c?.kind==='personal'?'estate':'personal',w.id))+'<p class="staff54-muted">产业雇佣由后人延续；个人聘约需当面商议。境界高低不阻止接续，欠薪仍须结清。</p>'+btn('协商结束聘约','leave',w.id)+'<details><summary>聘约往来</summary>'+((c?.history||[]).map(h=>'<p>'+esc(h.text)+'</p>').join('')||'<p>沿用原有产业雇佣，暂无新增聘约记录。</p>')+'</details></section></div></section>';}
function decorate(){if(!G||G.mode!=='idle')return;if(V.tab==='recruitOffers'){const scroll=document.getElementById('scene')?.querySelector('.sb-scroll');if(scroll?.parentNode&&notice&&!scroll.querySelector('.staff54-notice')){const line=document.createElement('p');line.className='staff54-notice';line.setAttribute('role','status');line.textContent=notice;scroll.prepend(line);}return;}if(V.tab!=='home'||V.sub!=='staff')return;const scene=document.getElementById('scene'),scroll=scene?.querySelector('.sb-scroll');if(!scroll?.parentNode||scroll.querySelector('.staff54-workspace'))return;const w=worker(V.worker);for(const b of scroll.querySelectorAll('[data-sb="assign"]'))if(w&&(w.training||pending(w)))b.disabled=true;if(!w)return;const mount=document.createElement('div');mount.innerHTML=panel(w);const section=mount.firstElementChild;const production=scroll.querySelector('[data-sb=assign],[data-sb=cancelJob]')?.closest('article');if(production){const fold=document.createElement('details');fold.className='staff54-production';fold.innerHTML='<summary>生产委派与安排</summary>';production.querySelector('[data-sb=dismiss]')?.remove();production.before(section);fold.append(production);section.append(fold);}else scroll.append(section);section.querySelectorAll('[data-staff54]').forEach(b=>b.onclick=()=>dispatch(b.dataset.staff54,b.dataset.person+(b.dataset.staff54==='break'?':'+(section.querySelector('[data-staff54-invest]')?.value||0):'')));const input=section.querySelector('[data-staff54-invest]');if(input)input.oninput=()=>{const quote=breakQuote(w,input.value);section.querySelector('[data-staff54-rate]').textContent='当前成算 '+Math.round((quote.rate||0)*100)+'%';};}
S.dispatch=function(action,arg){if(action?.startsWith('s54:'))return dispatch(action.slice(4),arg);const w=worker(String(arg||'').split(':')[0]);if(w&&action==='assign'&&(w.training||pending(w))){notice='当前培养或聘约状态不允许新增委派。';render();return;}if(w&&action==='dismiss')return dispatch('leave',w.id);return old.dispatch(action,arg);};
renderScene=function(...a){const result=old.scene(...a);decorate();return result;};
restore=function(raw){
 try{
  const incoming=JSON.parse(raw),incomingDay=Number.isFinite(incoming.t)?incoming.t*30+(incoming.day||0):null;
  for(const w of incoming.sandbox35?.staff||[]){
   const t=w.training;
   if(t&&(![t.start,t.end,t.last,t.budget,t.spent,t.carry].every(Number.isSafeInteger)||t.start<0||t.carry<0||t.carry>=30||t.end-t.start!==30||t.last<t.start||t.last>t.end||incomingDay!=null&&t.last>incomingDay||t.budget<0||t.spent!==Math.floor((t.carry+t.budget*(t.last-t.start))/30)||!PLACES[t.place]||!incoming.world36?.people?.[w.id]||w.job))throw Error('培养排程无效');
   const c=w.contract;
   if(c&&(!['estate','personal'].includes(c.kind)||!['active','pending'].includes(c.status)||typeof c.holder!=='string'||!Array.isArray(c.history)||c.history.length>16))throw Error('聘约无效');
  }
  for(const n of Object.values(incoming.world36?.people||{})){
   const extra=n.staff54;if(extra==null)continue;if(typeof extra!=='object'||Array.isArray(extra))throw Error('人手账目结构无效');
   if(n.cult!=null&&(!Number.isFinite(n.cult)||n.cult<0||!Number.isInteger(n.realm)||n.realm<0||n.realm>=REALMS.length||!Number.isInteger(n.layer)||n.layer<1||n.layer>realmLayerCount(n.realm)))throw Error('人手修为无效');
   if(extra.unpaidCurrency!=null&&!['wen','stone'].includes(extra.unpaidCurrency))throw Error('欠薪币种无效');
   if(extra.injuredUntil!=null&&!Number.isSafeInteger(extra.injuredUntil)||extra.budgetRemainder!=null&&(!Number.isInteger(extra.budgetRemainder)||extra.budgetRemainder<0||extra.budgetRemainder>=30)||extra.unpaidWages!=null&&(!Number.isSafeInteger(extra.unpaidWages)||extra.unpaidWages<0))throw Error('人手账目无效');
  }
 }catch(e){XTEconomy40.lastRestoreError='人手培养或聘约数据无效，当前档案保留。';return false;}
 return old.restore(raw);
};
window.XTStaff54={tick,stop,inherit,dispatch,trainReason,breakQuote,debtOf,debtCurrency,recordDebt};
})();
